INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 13, 'theory', 'Quiz: instruction decoder and control');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 0, 'What does the instruction decoder do?', '["Computes the result of an instruction", "Turns the operation code into control signals for the datapath", "Stores the program", "Sets the clock frequency"]', 1, 'The decoder links the instruction and the datapath: from the operation code it produces the write, operation-select, jump, and halt signals.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 1, 'Under what condition does the JNZ jump happen?', '["The instruction is JNZ and the accumulator is zero", "Always, for any instruction", "Only in the execute phase", "The instruction is JNZ and the accumulator is not zero (Z = 0)"]', 3, 'Take = JNZ · not Z. If the accumulator is zero, JNZ does nothing.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 2, 'How does the multiplexer choose the next address?', '["By the clock frequency", "By the accumulator value", "The Take selector chooses between \"PC + 1\" and the jump address k", "At random"]', 2, 'With Take = 0 the processor goes to the next instruction; with Take = 1 it jumps to the address in the operand.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 3, 'Why are clock phases needed?', '["So that control signals fire at the right moment: fetch, decode, execute, writeback", "To raise the frequency", "To save memory", "So that the processor can be stopped"]', 0, 'An instruction takes several clock cycles. The sequencer lights the phases in turn, and each control signal is an AND of a phase and a condition.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 13, 4, 'Why is halting the processor implemented with a latch?', '["It makes the circuit easier to draw", "A latch is faster than a gate", "The ALU requires it", "We must remember that Hlt occurred even after the signal itself is gone"]', 3, 'Hlt is present only while the instruction is on the bus. The Run latch is cleared by it and stays zero until the next reset.');
